	// MECHANISM-1: QueueDepth represents requests waiting (latency risk); BatchSize represents active work (throughput). Penalizing queue depth more heavily than batch size steers new requests away from backed-up instances
	// EXPECT-1: combined_score > -3930
	// HYPOTHESIS-2: Lowering KV threshold to 0.85 with a milder penalty catches memory pressure earlier without over-reacting, improving cache_warmup
	// MECHANISM-2: At 0.85 utilization, evictions are imminent; a 0.6x multiplier (vs 0.5x at 0.9) provides earlier but gentler steering that preserves more cache entries
	// EXPECT-2: cache_warmup_e2e_ms < 4210
	// RESULT-2: REFUTED (actual=4249.302709)

	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Find minimum load for normalization
	minLoad := snapshots[0].EffectiveLoad()
	minQueue := snapshots[0].QueueDepth
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if snap.QueueDepth < minQueue {
			minQueue = snap.QueueDepth
		}
	}

	// Targeted post-scoring adjustments
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()

		// Quadratic load penalty based on distance from minimum (confirmed effective)
		diff := float64(el - minLoad)
		if diff > 0 {
			penalty := 1.0 / (1.0 + 0.15*diff*diff)
			scores[snap.ID] *= penalty
		}

		// Extra queue-depth penalty: waiting requests are pure latency
		qDiff := float64(snap.QueueDepth - minQueue)
		if qDiff > 0 {
			qPenalty := 1.0 / (1.0 + 0.08*qDiff*qDiff)
			scores[snap.ID] *= qPenalty
		}

		// KV pressure penalty: earlier threshold, moderate penalty
		if snap.KVUtilization > 0.85 {
			scores[snap.ID] *= 0.55
		}
	}

	// Argmax: select instance with highest composite score
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
		snapshots[bestIdx].ID,
		fmt.Sprintf("weighted-scoring (score=%.3f)", bestScore),
		scores,
	)
